INSERT INTO `visa_info_versions` (`version_id`, `visa_type_id`, `version_no`, `name_mn`, `description`, `source_url`, `verified_at`, `verified_by`, `created_by`, `created_at`, `published_at`) VALUES (1,1,1,'Богино хугацааны аялал жуулчлал (C-3-9)','Богино хугацаагаар аялал жуулчлалын зорилгоор зорчих иргэдэд зориулсан ангилал. Материалын жагсаалтыг KVAC-ын нийтэд нээлттэй баримтад үндэслэв; ЭСЯ-ны шинэ журамтай тулгаж, мэдүүлэг өгөхийн өмнө дахин шалгана уу. Хураамж, шийдвэрлэх хугацааг тогтмол утгаар заахгүй — албан ёсны мэдэгдлийг үзнэ үү.','https://www.visaforkorea.mn/sites/g/files/tmzbdl2131/files/inline-files/C-3-9_Eng.pdf','2026-10-30',1,1,'2026-11-25 15:12:39.990724','2026-11-25 15:12:39.990724');
INSERT INTO `visa_info_versions` (`version_id`, `visa_type_id`, `version_no`, `name_mn`, `description`, `source_url`, `verified_at`, `verified_by`, `created_by`, `created_at`, `published_at`) VALUES (2,2,1,'Суралцах (D-2) — ноорог','Шаардлагыг баталгаажуулж байна.',NULL,NULL,NULL,1,'2026-11-25 15:12:39.994541',NULL);
INSERT INTO `visa_requirements` (`requirement_id`, `version_id`, `code`, `title`, `instructions`, `applies_to`, `original_or_copy`, `translation_note`, `is_required`, `sort_order`) VALUES (1,1,'FORM_PHOTO','Визийн анкет ба цээж зураг','Сүүлийн 6 сард авсан 3.5 × 4.5 см цээж зураг хавсаргана.','Бүх мэдүүлэгч','ORIGINAL','Анкетыг англи эсвэл солонгос хэлээр бөглөнө.',1,10);
INSERT INTO `visa_requirements` (`requirement_id`, `version_id`, `code`, `title`, `instructions`, `applies_to`, `original_or_copy`, `translation_note`, `is_required`, `sort_order`) VALUES (2,1,'PASSPORT_COPY','Гадаад паспортын хуулбар','Мэдээлэл бүхий хуудасны хуулбарыг байршуулна. Эх хувийг материал хүлээлгэн өгөхдөө заавал авч очно.','Бүх мэдүүлэгч','BOTH',NULL,1,20);
INSERT INTO `visa_requirements` (`requirement_id`, `version_id`, `code`, `title`, `instructions`, `applies_to`, `original_or_copy`, `translation_note`, `is_required`, `sort_order`) VALUES (3,1,'FINANCIAL','Санхүүгийн чадварын нотолгоо','Ажлын газрын тодорхойлолт, банкны хуулга г.м. Нэг баримтыг бүх хүнд ижил шаардахгүй.','Ажил, бизнес болон бусад нөхцөлөөс хамаарна',NULL,'Монгол баримтын орчуулгын шаардлагыг ЭСЯ-ны журмаас шалгана.',1,30);
INSERT INTO `visa_requirements` (`requirement_id`, `version_id`, `code`, `title`, `instructions`, `applies_to`, `original_or_copy`, `translation_note`, `is_required`, `sort_order`) VALUES (4,1,'FAMILY','Гэр бүлийн баримт (хамаарах бол)','Гэрлэлтийн лавлагаа; насанд хүрээгүй хүүхэдтэй зорчих бол нэмэлт баримт.','Гэрлэсэн эсвэл насанд хүрээгүй хүүхэдтэй зорчих мэдүүлэгч',NULL,NULL,0,40);
INSERT INTO `visa_requirements` (`requirement_id`, `version_id`, `code`, `title`, `instructions`, `applies_to`, `original_or_copy`, `translation_note`, `is_required`, `sort_order`) VALUES (5,1,'ADDITIONAL','Нэмэлт материал','ЭСЯ эсвэл оператор нэмэлт баримт шаардсан үед энд хавсаргана.','Шаардсан тохиолдолд',NULL,NULL,0,50);
